const fs=require('fs');
const files=fs.readdirSync('/opt/ada-src/.autoresearch/diagnostics');
for(const d of files){
  const p=`/opt/ada-src/.autoresearch/diagnostics/${d}/0.json`;
  if(!fs.existsSync(p))continue;
  const j=JSON.parse(fs.readFileSync(p,'utf8'));
  const s=JSON.stringify(j);
  if(!s.includes('servo'))continue;
  // find task objects
  function walk(o,path){
    if(Array.isArray(o)){o.forEach((v,i)=>walk(v,path+'['+i+']'));return;}
    if(o&&typeof o==='object'){
      if(o.task_id&&JSON.stringify(o).includes('servo')) console.log('FILE',d,'\n',JSON.stringify(o,null,1).slice(0,2000),'\n---');
      else if(o.id&&JSON.stringify(o).includes('servo')) console.log('FILE',d,'OBJ',JSON.stringify(o).slice(0,1500));
      for(const k in o)walk(o[k],path+'.'+k);
    }
  }
  walk(j,'');
}
EOF
timeout 60 /opt/ada-node /tmp/find_servo.js 2>&1 | head -120

